// Écrit par outils/agent_appels.py : ne pas modifier à la main.
// Chaque commande de l'appli que l'agent de BHOST OS sait faire : nom → fonction.

#[allow(unused_variables, clippy::let_unit_value)]
pub(crate) async fn appeler(app: &AppHandle, commande: &str, args: &Value) -> Result<Value, Value> {
    match commande {
        "lister_serveurs" => Ok(json(crate::lister_serveurs(app.state::<Etat>()))),
        "demarrer_serveur" => crate::demarrer_serveur(app.clone(), arg(args, "id")?).map(json).map_err(json),
        "installer_java_serveur" => crate::installer_java_serveur(app.clone(), arg(args, "id")?, arg(args, "version")?).map(json).map_err(json),
        "problemes_serveurs" => Ok(json(crate::problemes::problemes_serveurs())),
        "etat_internet" => Ok(json(crate::problemes::etat_internet())),
        "verifier_internet" => Ok(json(crate::problemes::verifier_internet(app.clone()).await)),
        "arreter_serveur" => crate::arreter_serveur(app.clone(), arg(args, "id")?).map(json).map_err(json),
        "redemarrer_serveur" => crate::redemarrer_serveur(app.clone(), arg(args, "id")?, app.state::<Etat>()).map(json).map_err(json),
        "forcer_arret" => crate::forcer_arret(arg(args, "id")?, app.state::<Etat>()).map(json).map_err(json),
        "envoyer_commande" => crate::envoyer_commande(app.clone(), arg(args, "id")?, arg(args, "commande")?, app.state::<Etat>()).map(json).map_err(json),
        "regarder_tps" => Ok(json(crate::regarder_tps(arg(args, "id")?, arg(args, "actif")?, app.state::<Etat>()))),
        "tete_joueur" => Ok(json(crate::tete_joueur(app.clone(), arg(args, "nom")?).await)),
        "renommer_serveur" => crate::renommer_serveur(arg(args, "id")?, arg(args, "nom")?, app.state::<Etat>()).map(json).map_err(json),
        "infos_creation" => Ok(json(crate::infos_creation(app.state::<Etat>()))),
        "versions_minecraft" => crate::versions_minecraft(app.clone(), arg(args, "logiciel")?, arg(args, "snapshots")?).await.map(json).map_err(json),
        "creer_serveur" => crate::creer_serveur(app.clone(), arg(args, "demande")?).await.map(json).map_err(json),
        "couleur_serveur" => crate::couleur_serveur(arg(args, "id")?, arg(args, "couleur")?, app.state::<Etat>()).map(json).map_err(json),
        "parametres_serveur" => crate::parametres_serveur(arg(args, "id")?, app.state::<Etat>()).map(json).map_err(json),
        "regler_serveur" => crate::regler_serveur(arg(args, "id")?, arg(args, "reglages")?, app.state::<Etat>()).map(json).map_err(json),
        "regler_partie" => crate::regler_partie(app.clone(), arg(args, "id")?, arg(args, "partie")?, app.state::<Etat>()).map(json).map_err(json),
        "dupliquer_serveur" => crate::dupliquer_serveur(app.clone(), arg(args, "id")?).await.map(json).map_err(json),
        "supprimer_serveur" => crate::supprimer_serveur(app.clone(), arg(args, "id")?).await.map(json).map_err(json),
        "retirer_serveur" => crate::retirer_serveur(app.clone(), arg(args, "id")?, app.state::<Etat>()).map(json).map_err(json),
        "lire_console" => Ok(json(crate::lire_console(arg(args, "id")?, app.state::<Etat>()))),
        "regles_serveur" => crate::regles_serveur(arg(args, "id")?, app.state::<Etat>()).map(json).map_err(json),
        "regler_regle" => crate::regler_regle(app.clone(), arg(args, "id")?, arg(args, "cle")?, arg(args, "valeur")?, app.state::<Etat>()).map(json).map_err(json),
        "mondes_serveur" => crate::mondes_serveur(app.clone(), arg(args, "id")?).await.map(json).map_err(json),
        "utiliser_monde" => crate::utiliser_monde(app.clone(), arg(args, "id")?, arg(args, "dossier")?).await.map(json).map_err(json),
        "nouveau_monde" => crate::nouveau_monde(app.clone(), arg(args, "id")?).await.map(json).map_err(json),
        "supprimer_monde" => crate::supprimer_monde(app.clone(), arg(args, "id")?, arg(args, "dossier")?).await.map(json).map_err(json),
        "reinitialiser_monde" => crate::reinitialiser_monde(app.clone(), arg(args, "id")?, arg(args, "dossier")?, arg(args, "memeGraine")?).await.map(json).map_err(json),
        "changer_version" => crate::changer_version(app.clone(), arg(args, "id")?, arg(args, "logiciel")?, arg(args, "version")?).await.map(json).map_err(json),
        "joueurs_serveur" => crate::joueurs_serveur(arg(args, "id")?, app.state::<Etat>()).map(json).map_err(json),
        "action_joueur" => crate::action_joueur(app.clone(), arg(args, "id")?, arg(args, "action")?, arg(args, "nom")?, arg(args, "motif")?).await.map(json).map_err(json),
        "repondre_demande" => crate::repondre_demande(app.clone(), arg(args, "id")?, arg(args, "nom")?, arg(args, "accepter")?).await.map(json).map_err(json),
        "liste_blanche" => crate::liste_blanche(app.clone(), arg(args, "id")?, arg(args, "active")?, app.state::<Etat>()).map(json).map_err(json),
        "fiche_joueur" => crate::fiche_joueur(app.clone(), arg(args, "id")?, arg(args, "nom")?).await.map(json).map_err(json),
        "commande_joueur" => crate::commande_joueur(app.clone(), arg(args, "id")?, arg(args, "nom")?, arg(args, "action")?, app.state::<Etat>()).map(json).map_err(json),
        "sauvegardes_serveur" => crate::sauvegardes_serveur(app.clone(), arg(args, "id")?).await.map(json).map_err(json),
        "regler_sauvegardes" => crate::regler_sauvegardes(arg(args, "id")?, arg(args, "reglages")?, app.state::<Etat>()).map(json).map_err(json),
        "sauvegarder_maintenant" => crate::sauvegarder_maintenant(app.clone(), arg(args, "id")?).await.map(json).map_err(json),
        "epingler_sauvegarde" => crate::epingler_sauvegarde(app.clone(), arg(args, "id")?, arg(args, "fichier")?, arg(args, "epinglee")?).await.map(json).map_err(json),
        "supprimer_sauvegarde" => crate::supprimer_sauvegarde(app.clone(), arg(args, "id")?, arg(args, "fichier")?).await.map(json).map_err(json),
        "restaurer_sauvegarde" => crate::restaurer_sauvegarde(app.clone(), arg(args, "id")?, arg(args, "fichier")?, arg(args, "tout")?).await.map(json).map_err(json),
        "fichiers_serveur" => crate::fichiers_serveur(app.clone(), arg(args, "id")?, arg(args, "dossier")?).await.map(json).map_err(json),
        "lire_fichier" => crate::lire_fichier(app.clone(), arg(args, "id")?, arg(args, "chemin")?).await.map(json).map_err(json),
        "ecrire_fichier" => crate::ecrire_fichier(arg(args, "id")?, arg(args, "chemin")?, arg(args, "texte")?, app.state::<Etat>()).map(json).map_err(json),
        "icone_du_jeu" => crate::icone_du_jeu(app.clone(), arg(args, "id")?, arg(args, "remettre")?).await.map(json).map_err(json),
        "proprietes_serveur" => crate::proprietes_serveur(arg(args, "id")?, app.state::<Etat>()).map(json).map_err(json),
        "regler_proprietes" => crate::regler_proprietes(arg(args, "id")?, arg(args, "valeurs")?, app.state::<Etat>()).map(json).map_err(json),
        "automatisations_serveur" => crate::automatique::automatisations_serveur(arg(args, "id")?, app.state::<Etat>()).map(json).map_err(json),
        "enregistrer_automatisation" => crate::automatique::enregistrer_automatisation(app.clone(), arg(args, "id")?, arg(args, "automatisation")?).map(json).map_err(json),
        "supprimer_automatisation" => crate::automatique::supprimer_automatisation(app.clone(), arg(args, "id")?, arg(args, "aid")?).map(json).map_err(json),
        "activer_automatisation" => crate::automatique::activer_automatisation(app.clone(), arg(args, "id")?, arg(args, "aid")?, arg(args, "on")?).map(json).map_err(json),
        "etats_acces" => Ok(json(crate::etats_acces(app.state::<Etat>()))),
        "ouvrir_aux_amis" => crate::ouvrir_aux_amis(app.clone(), arg(args, "id")?, arg(args, "ouvert")?, app.state::<Etat>()).map(json).map_err(json),
        "reglages_bhost" => crate::reglages_bhost(app.clone()).await.map(json).map_err(json),
        "regler_bhost" => crate::regler_bhost(app.clone(), arg(args, "changement")?).await.map(json).map_err(json),
        "extensions_serveur" => crate::catalogue::extensions_serveur(app.clone(), arg(args, "id")?, arg(args, "genre")?).await.map(json).map_err(json),
        "chercher_extensions" => crate::catalogue::chercher_extensions(app.clone(), arg(args, "id")?, arg(args, "texte")?, arg(args, "categorie")?, arg(args, "tri")?, arg(args, "page")?, arg(args, "genre")?).await.map(json).map_err(json),
        "installer_extension" => crate::catalogue::installer_extension(app.clone(), arg(args, "id")?, arg(args, "projet")?, arg(args, "genre")?).await.map(json).map_err(json),
        "activer_extension" => crate::catalogue::activer_extension(app.clone(), arg(args, "id")?, arg(args, "fichier")?, arg(args, "actif")?, arg(args, "genre")?, arg(args, "forcer")?).await.map(json).map_err(json),
        "datapacks_manquants" => Ok(json(crate::catalogue::datapacks_manquants(app.clone(), arg(args, "id")?))),
        "remettre_datapack" => crate::catalogue::remettre_datapack(app.clone(), arg(args, "id")?, arg(args, "fichier")?).await.map(json).map_err(json),
        "desinstaller_extension" => crate::catalogue::desinstaller_extension(app.clone(), arg(args, "id")?, arg(args, "fichier")?, arg(args, "genre")?, arg(args, "forcer")?).await.map(json).map_err(json),
        "mettre_a_jour_extensions" => crate::catalogue::mettre_a_jour_extensions(app.clone(), arg(args, "id")?, arg(args, "fichiers")?, arg(args, "genre")?).await.map(json).map_err(json),
        "bedrock_serveur" => crate::catalogue::bedrock_serveur(app.clone(), arg(args, "id")?).map(json).map_err(json),
        "regler_bedrock" => crate::catalogue::regler_bedrock(app.clone(), arg(args, "id")?, arg(args, "actif")?).await.map(json).map_err(json),
        _ => Err(json(format!("Commande inconnue : {commande}"))),
    }
}

